package mojoanything;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.Supplier;

/** Generated by mojo-anything: the binary wire to the Rust port. Little endian; nullable values start with 0 for null. */
public final class MojoAnythingWire {
    private MojoAnythingWire() {}

    public static final class Writer {
        private byte[] buf = new byte[64];
        private int n;

        private void ensure(int more) {
            if (n + more > buf.length) {
                buf = java.util.Arrays.copyOf(buf, Math.max(buf.length * 2, n + more));
            }
        }

        public void tag(int t) {
            ensure(1);
            buf[n++] = (byte) t;
        }

        public void len(int v) {
            ensure(4);
            for (int i = 0; i < 4; i++) {
                buf[n++] = (byte) (v >>> (8 * i));
            }
        }

        public void i64(long v) {
            ensure(8);
            for (int i = 0; i < 8; i++) {
                buf[n++] = (byte) (v >>> (8 * i));
            }
        }

        public void f64(double v) {
            i64(Double.doubleToRawLongBits(v));
        }

        public void bool(boolean v) {
            tag(v ? 1 : 0);
        }

        public void str(String s) {
            if (s == null) {
                tag(0);
                return;
            }
            byte[] b = s.getBytes(StandardCharsets.UTF_8);
            tag(1);
            len(b.length);
            ensure(b.length);
            System.arraycopy(b, 0, buf, n, b.length);
            n += b.length;
        }

        public byte[] bytes() {
            return java.util.Arrays.copyOf(buf, n);
        }
    }

    public static final class Reader {
        private final byte[] b;
        private int i;

        public Reader(byte[] b) {
            this.b = b;
        }

        public int tag() {
            return b[i++] & 0xff;
        }

        public int len() {
            int v = 0;
            for (int k = 0; k < 4; k++) {
                v |= (b[i++] & 0xff) << (8 * k);
            }
            return v;
        }

        public long i64() {
            long v = 0;
            for (int k = 0; k < 8; k++) {
                v |= (long) (b[i++] & 0xff) << (8 * k);
            }
            return v;
        }

        public double f64() {
            return Double.longBitsToDouble(i64());
        }

        public boolean bool() {
            return tag() != 0;
        }

        public String str() {
            if (tag() == 0) {
                return null;
            }
            int n = len();
            String s = new String(b, i, n, StandardCharsets.UTF_8);
            i += n;
            return s;
        }

        public <T> List<T> list(Supplier<T> item) {
            if (tag() == 0) {
                return null;
            }
            int n = len();
            List<T> out = new ArrayList<>(n);
            for (int k = 0; k < n; k++) {
                out.add(item.get());
            }
            return out;
        }

        public <T> T[] array(Supplier<T> item, IntFunction<T[]> make) {
            List<T> items = list(item);
            return items == null ? null : items.toArray(make.apply(items.size()));
        }

        public <T> Map<String, T> map(Supplier<T> item) {
            if (tag() == 0) {
                return null;
            }
            int n = len();
            Map<String, T> out = new LinkedHashMap<>();
            for (int k = 0; k < n; k++) {
                String key = str();
                out.put(key, item.get());
            }
            return out;
        }

        public int[] ints() {
            if (tag() == 0) {
                return null;
            }
            int[] out = new int[len()];
            for (int k = 0; k < out.length; k++) {
                out[k] = (int) i64();
            }
            return out;
        }

        public long[] longs() {
            if (tag() == 0) {
                return null;
            }
            long[] out = new long[len()];
            for (int k = 0; k < out.length; k++) {
                out[k] = i64();
            }
            return out;
        }

        public double[] doubles() {
            if (tag() == 0) {
                return null;
            }
            double[] out = new double[len()];
            for (int k = 0; k < out.length; k++) {
                out[k] = f64();
            }
            return out;
        }

        public boolean[] booleans() {
            if (tag() == 0) {
                return null;
            }
            boolean[] out = new boolean[len()];
            for (int k = 0; k < out.length; k++) {
                out[k] = bool();
            }
            return out;
        }
    }
}

