            long out = n_gcd(a, b, slot);
            MojoAnythingError.check(slot);
            return out;
        } catch (MojoAnythingError e) {
            throw e.real();
        }
    }

    public static int call_pages(int total, int perPage) {
        try {
            String[] slot = MojoAnythingError.slot();
            int out = n_pages(total, perPage, slot);
            MojoAnythingError.check(slot);
