        let n = self.count()?;
        Ok(Some(String::from_utf8_lossy(self.take(n)?).into_owned()))
    }

    pub fn string(&mut self) -> Result<String, String> {
        self.opt_string()?
            .ok_or_else(|| "NullPointerException: null string".to_string())
    }

