    pub fn opt_js<T>(
        &mut self,
        item: impl FnOnce(&mut Self) -> Result<T, String>,
    ) -> Result<Option<T>, String> {
        if self.tag()? == 1 {
            item(self).map(Some)
        } else {
            Ok(None)
        }
    }

    pub fn required_js<T>(
        &mut self,
        item: impl FnOnce(&mut Self) -> Result<T, String>,
    ) -> Result<T, String> {
        self.opt_js(item)?
            .ok_or_else(|| "TypeError: expected a value, got undefined or null".to_string())
