        if self.tag()? == 0 {
            return Ok(Vec::new());
        }
        let n = self.count()?;
        let mut out = Vec::with_capacity(n.min(1 << 16));
        for _ in 0..n {
            let key = self.string16()?;
            out.push((key, item(self)?));
        }
        Ok(out)
    }

    /// A list; nil reads as empty.
    pub fn list<T>(
        &mut self,
        mut item: impl FnMut(&mut Self) -> Result<T, String>,
    ) -> Result<Vec<T>, String> {
        if self.tag()? == 0 {
            return Ok(Vec::new());
        }
        let n = self.count()?;
        let mut out = Vec::with_capacity(n.min(1 << 16));
        for _ in 0..n {
            out.push(item(self)?);
        }
        Ok(out)
    }

    /// A map's entries; nil reads as empty.
    pub fn map<T>(
        &mut self,
        mut item: impl FnMut(&mut Self) -> Result<T, String>,
    ) -> Result<Vec<(String, T)>, String> {
        if self.tag()? == 0 {
            return Ok(Vec::new());
        }
        let n = self.count()?;
        let mut out = Vec::with_capacity(n.min(1 << 16));
        for _ in 0..n {
