                handle = 0;
            }
        }

        synchronized long get() {
            if (handle == 0) {
                throw new IllegalStateException("PagesBatch is closed");
            }
            return handle;
        }
    }

    private final State state;
    private final java.lang.ref.Cleaner.Cleanable cleanable;
    private final int count;

    /** Copies the items into Rust. */
    public PagesBatch(int[] totals) {
        state = new State(nNew(totals));
        count = totals.length;
        cleanable = CLEANER.register(this, state);
    }

    private long handle() {
        return state.get();
    }

    /** {@code pages}'s result for every item, in order. */
    public int[] run(int perPage) {
        String[] slot = MojoAnythingError.slot();
        int[] out = nRun(handle(), perPage, slot);
        MojoAnythingError.check(slot);
        java.lang.ref.Reference.reachabilityFence(this);
        return out;
    }

    /** Indexes of the items whose result is at least {@code min}, highest result first. */
    public int[] rank(int perPage, double min) {
        String[] slot = MojoAnythingError.slot();
        int[] out = nRank(handle(), perPage, min, slot);
        MojoAnythingError.check(slot);
        java.lang.ref.Reference.reachabilityFence(this);
        return out;
    }

    private static native int[] nRank(long handle, int perPage, double min, String[] slot);

    /** Frees the items on the Rust side. */
