            Map<String, Object> map = new LinkedHashMap<>();
            pos[0]++;
            skip(s, pos);
            if (s.charAt(pos[0]) == '}') {
                pos[0]++;
                return map;
            }
            while (true) {
                skip(s, pos);
                String key = string(s, pos);
                skip(s, pos);
                pos[0]++; // ':'
                map.put(key, value(s, pos));
                skip(s, pos);
                if (s.charAt(pos[0]++) == '}') {
                    return map;
                }
            }
        }
        if (c == '[') {
            List<Object> list = new ArrayList<>();
            pos[0]++;
            skip(s, pos);
            if (s.charAt(pos[0]) == ']') {
                pos[0]++;
                return list;
            }
            while (true) {
                list.add(value(s, pos));
                skip(s, pos);
                if (s.charAt(pos[0]++) == ']') {
                    return list;
                }
            }
        }
        if (c == '"') {
            return string(s, pos);
        }
        if (s.startsWith("true", pos[0])) {
            pos[0] += 4;
            return Boolean.TRUE;
        }
        if (s.startsWith("false", pos[0])) {
            pos[0] += 5;
            return Boolean.FALSE;
        }
        if (s.startsWith("null", pos[0])) {
            pos[0] += 4;
            return null;
        }
        int start = pos[0];
        while (pos[0] < s.length() && "+-0123456789.eE".indexOf(s.charAt(pos[0])) >= 0) {
            pos[0]++;
