    m.add_function(wrap_pyfunction!(page_count, m)?)?;
    m.add_function(wrap_pyfunction!(mean, m)?)?;
    m.add_class::<Stack>()?;
    m.add_class::<SlugifyBatch>()?;
    m.add_class::<PageCountBatch>()?;
    Ok(())
}

