/// A Rust result as a Python object, without going through JSON.
pub trait ToPy {
    fn to_py(&self, py: Python<'_>) -> PyResult<Py<PyAny>>;
}

macro_rules! extract {
    ($($t:ty),*) => {$(
        impl FromPy for $t {
            fn from_py(obj: &Bound<'_, PyAny>) -> Result<Self, String> {
                obj.extract::<$t>().map_err(|_| type_error(obj))
