impl<T: ToPy> ToPy for std::collections::HashMap<String, T> {
    fn to_py(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let dict = PyDict::new(py);
        for (k, v) in self {
            dict.set_item(k, v.to_py(py)?)?;
        }
        Ok(dict.into_any().unbind())
    }
}

macro_rules! tuples {
    ($(($($t:ident $i:tt),+)),*) => {$(
