//! Ruby extension for `lib/textkit/`, generated by mojo-anything from `src/port.rs`. Regenerate with
//! `mojo-anything refresh`. Values convert directly between Ruby and Rust: no JSON.

use magnus::{Error, ExceptionClass, Module, Object, Ruby, function, method};
#[allow(unused_imports)]
use serde_json::Value;

pub mod port;

/// Batches allocate on all cores at once; mimalloc keeps that from serializing.
#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

mod rbconv;

/// `Err("ArgumentError: message")` raises that exception class; otherwise a RuntimeError.
fn error(ruby: &Ruby, message: String) -> Error {
    if let Some((kind, text)) = message.split_once(": ")
        && kind.starts_with(|c: char| c.is_ascii_uppercase())
        && kind.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        && let Ok(class) = ruby.class_object().const_get::<_, ExceptionClass>(kind)
    {
        return Error::new(class, text.to_string());
    }
    Error::new(ruby.exception_runtime_error(), message)
}

/// Runs the port; a panic becomes a RuntimeError instead of Ruby's uncatchable `fatal`.
fn guard<T>(ruby: &Ruby, f: impl FnOnce() -> Result<T, String>) -> Result<T, Error> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(result) => result.map_err(|m| error(ruby, m)),
        Err(panic) => {
            let text = panic
                .downcast_ref::<&str>()
                .map(ToString::to_string)
                .or_else(|| panic.downcast_ref::<String>().cloned())
                .unwrap_or_default();
            Err(Error::new(
                ruby.exception_runtime_error(),
                format!("Rust panic: {text}"),
            ))
        }
    }
}

/// `page_count`.
fn rb_page_count(ruby: &Ruby, total: i64, per_page: i64) -> Result<i64, Error> {
    guard(ruby, || port::page_count(total, per_page))
}

/// `mean`.
fn rb_mean(ruby: &Ruby, values: Vec<f64>) -> Result<Option<f64>, Error> {
    guard(ruby, || port::mean(values))
}

/// `clamp`.
fn rb_clamp(ruby: &Ruby, value: i64, low: i64, high: i64) -> Result<i64, Error> {
    guard(ruby, || port::clamp(value, low, high))
}

/// `slugify`.
fn rb_slugify(ruby: &Ruby, text: String, sep: String, max: Option<i64>) -> Result<String, Error> {
    guard(ruby, || port::slugify(text, sep, max))
}

/// `word_count`.
fn rb_word_count(ruby: &Ruby, text: String) -> Result<magnus::Value, Error> {
    guard(ruby, || port::word_count(text)).and_then(|out| rbconv::to_rb(ruby, &out))
}

/// `titleize`.
fn rb_titleize(ruby: &Ruby, text: String) -> Result<String, Error> {
    guard(ruby, || port::titleize(text))
}

/// The items of `SlugifyBatch` as the port takes them; the port runs per item. Define
/// `pub struct SlugifyIndex` in `port.rs` (with `new` and `run`) to prepare items once.
pub struct SlugifyDefaultIndex {
    items: Vec<String>,
}

impl SlugifyDefaultIndex {
    pub fn new(items: Vec<String>) -> Self {
        Self { items }
    }

    pub fn run(&self, sep: String, max: Option<i64>) -> Result<Vec<String>, String> {
        use rayon::prelude::*;
        self.items
            .par_iter()
            .map(|item| port::slugify(item.clone(), sep.clone(), max))
            .collect::<Vec<_>>()
            .into_iter()
            .collect()
    }
}

/// `slugify` over many `text` values kept in Rust: `run` maps them all in one call, on
/// all cores; `rank` returns the indexes of results >= `min`, best first.
#[magnus::wrap(
    class = "MojoAnythingNativeTextkitRs::SlugifyBatch",
    free_immediately,
    size
)]
pub struct SlugifyBatch {
    inner: SlugifyDefaultIndex,
}

impl SlugifyBatch {
    fn new(ruby: &Ruby, items: Vec<String>) -> Result<Self, Error> {
        guard(ruby, || {
            Ok(Self {
                inner: SlugifyDefaultIndex::new(items),
            })
        })
    }

    fn run(
        ruby: &Ruby,
        rb_self: &Self,
        sep: String,
        max: Option<i64>,
    ) -> Result<Vec<String>, Error> {
        guard(ruby, || rb_self.inner.run(sep, max))
    }
}

/// The items of `PageCountBatch` as the port takes them; the port runs per item. Define
/// `pub struct PageCountIndex` in `port.rs` (with `new` and `run`) to prepare items once.
pub struct PageCountDefaultIndex {
    items: Vec<i64>,
}

impl PageCountDefaultIndex {
    pub fn new(items: Vec<i64>) -> Self {
        Self { items }
    }

    pub fn run(&self, per_page: i64) -> Result<Vec<i64>, String> {
        use rayon::prelude::*;
        self.items
            .par_iter()
            .map(|item| port::page_count(*item, per_page))
            .collect::<Vec<_>>()
            .into_iter()
            .collect()
    }
}

/// `page_count` over many `total` values kept in Rust: `run` maps them all in one call, on
/// all cores; `rank` returns the indexes of results >= `min`, best first.
#[magnus::wrap(
    class = "MojoAnythingNativeTextkitRs::PageCountBatch",
    free_immediately,
    size
)]
pub struct PageCountBatch {
    inner: PageCountDefaultIndex,
}

impl PageCountBatch {
    fn new(ruby: &Ruby, items: Vec<i64>) -> Result<Self, Error> {
        guard(ruby, || {
            Ok(Self {
                inner: PageCountDefaultIndex::new(items),
            })
        })
    }

    fn run(ruby: &Ruby, rb_self: &Self, per_page: i64) -> Result<Vec<i64>, Error> {
        guard(ruby, || rb_self.inner.run(per_page))
    }

    fn rank(ruby: &Ruby, rb_self: &Self, per_page: i64, min: f64) -> Result<Vec<u32>, Error> {
        let out = guard(ruby, || rb_self.inner.run(per_page))?;
        let mut hits: Vec<(f64, u32)> = out
            .into_iter()
            .enumerate()
            .map(|(i, r)| (r as f64, u32::try_from(i).unwrap_or(u32::MAX)))
            .filter(|(r, _)| *r >= min)
            .collect();
        // Stable: equal results keep the items' order, as JS `sort` and Python `sorted` do.
        hits.sort_by(|a, b| b.0.total_cmp(&a.0));
        let order: Vec<u32> = hits.into_iter().map(|(_, i)| i).collect();
        Ok(order)
    }
}

/// The items of `WordCountBatch` as the port takes them; the port runs per item. Define
/// `pub struct WordCountIndex` in `port.rs` (with `new` and `run`) to prepare items once.
pub struct WordCountDefaultIndex {
    items: Vec<String>,
}

impl WordCountDefaultIndex {
    pub fn new(items: Vec<String>) -> Self {
        Self { items }
    }

    pub fn run(&self) -> Result<Vec<Value>, String> {
        use rayon::prelude::*;
        self.items
            .par_iter()
            .map(|item| port::word_count(item.clone()))
            .collect::<Vec<_>>()
            .into_iter()
            .collect()
    }
}

/// `word_count` over many `text` values kept in Rust: `run` maps them all in one call, on
/// all cores; `rank` returns the indexes of results >= `min`, best first.
#[magnus::wrap(
    class = "MojoAnythingNativeTextkitRs::WordCountBatch",
    free_immediately,
    size
)]
pub struct WordCountBatch {
    inner: WordCountDefaultIndex,
}

impl WordCountBatch {
    fn new(ruby: &Ruby, items: Vec<String>) -> Result<Self, Error> {
        guard(ruby, || {
            Ok(Self {
                inner: WordCountDefaultIndex::new(items),
            })
        })
    }

    fn run(ruby: &Ruby, rb_self: &Self) -> Result<magnus::RArray, Error> {
        guard(ruby, || rb_self.inner.run()).and_then(|out| {
            let array = ruby.ary_new_capa(out.len());
            for v in &out {
                array.push(rbconv::to_rb(ruby, v)?)?;
            }
            Ok(array)
        })
    }
}

#[magnus::init(name = "textkit_rs_native")]
fn init(ruby: &Ruby) -> Result<(), Error> {
    let native = ruby.define_module("MojoAnythingNativeTextkitRs")?;
    native.define_module_function("page_count", function!(rb_page_count, 2))?;
    native.define_module_function("mean", function!(rb_mean, 1))?;
    native.define_module_function("clamp", function!(rb_clamp, 3))?;
    native.define_module_function("slugify", function!(rb_slugify, 3))?;
    native.define_module_function("word_count", function!(rb_word_count, 1))?;
    native.define_module_function("titleize", function!(rb_titleize, 1))?;
    let class = native.define_class("SlugifyBatch", ruby.class_object())?;
    class.define_singleton_method("new", function!(SlugifyBatch::new, 1))?;
    class.define_method("run", method!(SlugifyBatch::run, 2))?;
    let class = native.define_class("PageCountBatch", ruby.class_object())?;
    class.define_singleton_method("new", function!(PageCountBatch::new, 1))?;
    class.define_method("run", method!(PageCountBatch::run, 1))?;
    class.define_method("rank", method!(PageCountBatch::rank, 2))?;
    let class = native.define_class("WordCountBatch", ruby.class_object())?;
    class.define_singleton_method("new", function!(WordCountBatch::new, 1))?;
    class.define_method("run", method!(WordCountBatch::run, 0))?;
    Ok(())
}

