// mojoAnythingValidUTF8 says whether every string in v is UTF-8: json.Marshal would replace
// invalid bytes with U+FFFD and the port would see other text.
func mojoAnythingValidUTF8(v reflect.Value) bool {
	switch v.Kind() {
	case reflect.String:
