            if not failed:
                if s[i] == SLASH:
                    failed = True
                var r: UInt32 = 0
                i += _decode_rune(s, i, r)
            c += 1
        else:
            var literal = ch
            if ch == 92:
                c += 1
                if c >= end:
                    raise Error(BAD_PATTERN)
                literal = p[c]
            if not failed:
                if literal != s[i]:
                    failed = True
                i += 1
            c += 1
    return -1 if failed else i


