        if t >= 0 and (t == len(s) or pi < len(p)):
            ni = t
            continue
        if star:
            var found = False
            var k = ni
            while k < len(s) and s[k] != SLASH:
                var t2 = _match_chunk(p, start, end, s, k + 1)
                if t2 >= 0:
                    if pi == len(p) and t2 != len(s):
