// Package path is the Mojo port of `path/`, generated by mojo-anything: the same API, each
// function calling the Mojo library. Regenerate with `mojo-anything refresh`.
package path

/*
#cgo LDFLAGS: -L${SRCDIR}/../.mojo-anything/build -lpath_mojo -Wl,-rpath,${SRCDIR}/../.mojo-anything/build
#include <stdint.h>
#include <stdlib.h>
char *mojo_anything_call(const char *name, const char *args);
void mojo_anything_free(char *ptr);
int mojo_anything_t_Match(const uint8_t *ra_arg0_ptr, size_t ra_arg0_len, const uint8_t *ra_arg1_ptr, size_t ra_arg1_len, uint8_t *out, char **err);
int mojo_anything_t_Clean(const uint8_t *ra_arg0_ptr, size_t ra_arg0_len, uint8_t *out, size_t out_cap, size_t *out_len, char **err);
int mojo_anything_t_Ext(const uint8_t *ra_arg0_ptr, size_t ra_arg0_len, uint8_t *out, size_t out_cap, size_t *out_len, char **err);
int mojo_anything_t_Base(const uint8_t *ra_arg0_ptr, size_t ra_arg0_len, uint8_t *out, size_t out_cap, size_t *out_len, char **err);
int mojo_anything_t_IsAbs(const uint8_t *ra_arg0_ptr, size_t ra_arg0_len, uint8_t *out, char **err);
int mojo_anything_t_Dir(const uint8_t *ra_arg0_ptr, size_t ra_arg0_len, uint8_t *out, size_t out_cap, size_t *out_len, char **err);
*/
import "C"

import (
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"reflect"
	"unicode/utf8"
	"unsafe"
)

var _ = json.Marshal
var _ = errors.New
var _ = fmt.Sprint
var _ = math.NaN
var _ = reflect.ValueOf
var _ = utf8.ValidString
var _ = unsafe.Pointer(nil)

// mojoAnythingDecode decodes JSON into target; floats may be {"$num": "NaN" | "Infinity" | ...}.
func mojoAnythingDecode(raw json.RawMessage, target any) error {
	if f, ok := target.(*float64); ok && len(raw) > 0 && raw[0] == '{' {
		var marker map[string]string
		if err := json.Unmarshal(raw, &marker); err != nil {
			return err
		}
		switch marker["$num"] {
		case "NaN":
			*f = math.NaN()
		case "Infinity":
			*f = math.Inf(1)
		case "-Infinity":
			*f = math.Inf(-1)
		case "-0":
			*f = math.Copysign(0, -1)
		default:
			return errors.New("not a number")
		}
		return nil
	}
	if len(raw) == 0 {
		raw = json.RawMessage("null")
	}
	return json.Unmarshal(raw, target)
}

// mojoAnythingEncode marks the floats JSON cannot carry.
func mojoAnythingEncode(v any) any {
	var f float64
	switch x := v.(type) {
	case float64:
		f = x
	case float32:
		f = float64(x)
	default:
		return v
	}
	switch {
	case math.IsNaN(f):
		return map[string]string{"$num": "NaN"}
	case math.IsInf(f, 1):
		return map[string]string{"$num": "Infinity"}
	case math.IsInf(f, -1):
		return map[string]string{"$num": "-Infinity"}
	case f == 0 && math.Signbit(f):
		return map[string]string{"$num": "-0"}
	}
	return v
}

type mojoAnythingAnswer struct {
	Ok    json.RawMessage `json:"ok"`
	Error *string         `json:"error"`
	Panic *string         `json:"panic"`
}

// mojoAnythingValidUTF8 says whether every string in v is UTF-8: json.Marshal would replace
// invalid bytes with U+FFFD and the port would see other text.
func mojoAnythingValidUTF8(v reflect.Value) bool {
	switch v.Kind() {
	case reflect.String:
		return utf8.ValidString(v.String())
	case reflect.Pointer, reflect.Interface:
		return v.IsNil() || mojoAnythingValidUTF8(v.Elem())
	case reflect.Slice, reflect.Array:
		if v.Kind() == reflect.Slice && v.Type().Elem().Kind() == reflect.Uint8 {
			return true // []byte crosses as base64
		}
		for i := 0; i < v.Len(); i++ {
			if !mojoAnythingValidUTF8(v.Index(i)) {
				return false
			}
		}
	case reflect.Map:
		for it := v.MapRange(); it.Next(); {
			if !mojoAnythingValidUTF8(it.Key()) || !mojoAnythingValidUTF8(it.Value()) {
				return false
			}
		}
	case reflect.Struct:
		for i := 0; i < v.NumField(); i++ {
			if v.Type().Field(i).IsExported() && !mojoAnythingValidUTF8(v.Field(i)) {
				return false
			}
		}
	}
	return true
}

func mojoAnythingCall(name string, args ...any) (json.RawMessage, error) {
	for i, a := range args {
		if !mojoAnythingValidUTF8(reflect.ValueOf(a)) {
			panic(fmt.Sprintf("mojo-anything: argument %d of %s holds invalid UTF-8, which the JSON dispatcher cannot carry", i+1, name))
		}
		args[i] = mojoAnythingEncode(a)
	}
	encoded, err := json.Marshal(args)
	if err != nil {
		panic(err)
	}
	cName := C.CString(name)
	defer C.free(unsafe.Pointer(cName))
	cArgs := C.CString(string(encoded))
	defer C.free(unsafe.Pointer(cArgs))
	answer := C.mojo_anything_call(cName, cArgs)
	if answer == nil {
		panic("mojo-anything: the dispatcher could not allocate its answer")
	}
	defer C.mojo_anything_free(answer)
	var a mojoAnythingAnswer
	if err := json.Unmarshal([]byte(C.GoString(answer)), &a); err != nil {
		panic(err)
	}
	if a.Panic != nil {
		panic(*a.Panic)
	}
	if a.Error != nil {
		return nil, errors.New(*a.Error)
	}
	return a.Ok, nil
}

func mojoAnythingMust(err error) {
	if err != nil {
		panic(err)
	}
}

// mojoAnythingStr is a string's bytes for C, without copying; nil for "".
func mojoAnythingStr(s string) *C.uint8_t {
	if len(s) == 0 {
		return nil
	}
	return (*C.uint8_t)(unsafe.Pointer(unsafe.StringData(s)))
}

// mojoAnythingBool is a bool for C.
func mojoAnythingBool(b bool) C.uint8_t {
	if b {
		return 1
	}
	return 0
}

// mojoAnythingErr takes the error message the Mojo side allocated.
func mojoAnythingErr(p *C.char) string {
	msg := C.GoString(p)
	C.mojo_anything_free(p)
	return msg
}

// Match is the Mojo port of `func Match(pattern, name string) (matched bool, err error)` (`path/match.go:37`): a typed call, no JSON.
func Match(raArg0 string, raArg1 string) (bool, error) {
	var errp *C.char
	var out C.uint8_t
	status := C.mojo_anything_t_Match(mojoAnythingStr(raArg0), C.size_t(len(raArg0)), mojoAnythingStr(raArg1), C.size_t(len(raArg1)), &out, &errp)
	if status == 1 {
		return false, errors.New(mojoAnythingErr(errp))
	}
	return out != 0, nil
}

// Clean is the Mojo port of `func Clean(path string) string` (`path/path.go:72`): a typed call, no JSON.
func Clean(raArg0 string) string {
	var errp *C.char
