	buf := stack[:]
	var n C.size_t
	status := C.mojo_anything_t_Clean(mojoAnythingStr(raArg0), C.size_t(len(raArg0)), (*C.uint8_t)(unsafe.Pointer(&buf[0])), C.size_t(len(buf)), &n, &errp)
