# The JSON dispatcher for the Mojo port of `src/main/java/com/example/jdk/`, generated by mojo-anything. Regenerate
# with `mojo-anything refresh`.

from std.ffi import external_call
from std.memory import Pointer

from emberjson import Array, Object
from json import JsonValue, as_float, json_array, json_bool, json_float, json_int, json_string, json_uint, parse_json, write_json

import port


def _undefined() raises -> JsonValue:
    # JS's `undefined`, as the TS codec carries it.
    var o = Object()
    o["$undefined"] = JsonValue(True)
    return JsonValue(o^)

def _bytes_text(p: Optional[Pointer[Int8, ImmutAnyOrigin]]) -> String:
    # SAFETY: the caller passes NULL or a NUL-terminated string valid for the call. The bytes
    # are UTF-8 JSON; they are copied as they are.
    if not p:
        return String()
    var ptr = p.value().unsafe_bitcast[UInt8]()
    var n = 0
    while ptr[unsafe_offset=n] != 0:
        n += 1
    return String(
        unsafe_from_utf8=Span[UInt8, ImmutAnyOrigin](unsafe_ptr=ptr, length=n)
    )


def _answer(s: String) -> Optional[Pointer[Int8, MutAnyOrigin]]:
    var b = s.as_bytes()
    var n = len(b)
    var p = external_call["malloc", Optional[Pointer[UInt8, MutAnyOrigin]]](n + 1)
    if not p:
        return None
    var q = p.value()
    for i in range(n):
        q[unsafe_offset=i] = b[i]
    q[unsafe_offset=n] = 0
    return q.unsafe_bitcast[Int8]()


def _tagged(tag: String, message: String) -> String:
    var o = Object()
    o[tag] = JsonValue(message)
    try:
        return write_json(JsonValue(o^))
    except:
        return '{"panic":"the dispatcher could not write its answer"}'


def _panic(message: String) -> String:
    return _tagged("panic", message)


def _error(message: String) -> String:
    return _tagged("error", message)


def _ok(v: JsonValue) -> String:
    try:
        return '{"ok":' + write_json(v) + "}"
    except e:
        return _panic("the result does not write as JSON: " + String(e))


def _from_json_Int32(v: JsonValue) raises -> Int32:
    return Int32(json_int(v, -2147483648, 2147483647))


def _to_json_String(v: String) raises -> JsonValue:
    return JsonValue(String(v))


def _from_json_String(v: JsonValue) raises -> String:
    return json_string(v)


def _to_json_Int32(v: Int32) raises -> JsonValue:
    return JsonValue(Int64(v))


def _from_json_Int64(v: JsonValue) raises -> Int64:
    return Int64(json_int(v, Int64.MIN, Int64.MAX))


def _from_json_Float64(v: JsonValue) raises -> Float64:
    return as_float(v)


def _call_to_radix(args: Array) -> String:
    if len(args) != 2:
        return _panic("toRadix takes 2 arguments, got " + String(len(args)))
    var a0: Int32
    var a1: Int32
    try:
        a0 = _from_json_Int32(args[0])
        a1 = _from_json_Int32(args[1])
    except e:
        return _panic("toRadix: " + String(e))
    try:
        var out = _to_json_String(port.to_radix(a0, a1))
        return _ok(out)
    except e:
        return _error(String(e))


def _call_parse_radix(args: Array) -> String:
    if len(args) != 2:
        return _panic("parseRadix takes 2 arguments, got " + String(len(args)))
    var a0: String
    var a1: Int32
    try:
        a0 = _from_json_String(args[0])
        a1 = _from_json_Int32(args[1])
    except e:
        return _panic("parseRadix: " + String(e))
    try:
        var out = _to_json_Int32(port.parse_radix(a0, a1))
        return _ok(out)
    except e:
        return _error(String(e))


def _call_to_binary(args: Array) -> String:
    if len(args) != 1:
        return _panic("toBinary takes 1 argument, got " + String(len(args)))
    var a0: Int32
    try:
        a0 = _from_json_Int32(args[0])
    except e:
        return _panic("toBinary: " + String(e))
    try:
        var out = _to_json_String(port.to_binary(a0))
        return _ok(out)
    except e:
        return _error(String(e))


def _call_to_hex(args: Array) -> String:
    if len(args) != 1:
        return _panic("toHex takes 1 argument, got " + String(len(args)))
    var a0: Int64
    try:
        a0 = _from_json_Int64(args[0])
    except e:
        return _panic("toHex: " + String(e))
    try:
        var out = _to_json_String(port.to_hex(a0))
        return _ok(out)
    except e:
        return _error(String(e))


def _call_reverse_bits(args: Array) -> String:
    if len(args) != 1:
        return _panic("reverseBits takes 1 argument, got " + String(len(args)))
    var a0: Int32
    try:
        a0 = _from_json_Int32(args[0])
