package mojoanything;

import java.lang.reflect.Array;
import java.lang.reflect.GenericArrayType;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Generated by mojo-anything: a dependency-free JSON codec for the bridge. */
public final class MojoAnythingJson {
    private MojoAnythingJson() {}

    /** Captures a generic type: {@code new TypeRef<List<String>>() {}.type()}. */
    public abstract static class TypeRef<T> {
        public Type type() {
            return ((ParameterizedType) getClass().getGenericSuperclass()).getActualTypeArguments()[0];
        }
    }

    /** A value that does not fit the declared type. */
    public static final class Mismatch extends RuntimeException {
        public Mismatch(String message) {
            super(message);
        }
    }

    // ---- parse ----

    public static Object parse(String text) {
        int[] pos = {0};
        Object value = value(text, pos);
        skip(text, pos);
        if (pos[0] != text.length()) {
            throw new IllegalArgumentException("trailing JSON at " + pos[0]);
        }
        return value;
    }

    private static void skip(String s, int[] pos) {
        while (pos[0] < s.length() && Character.isWhitespace(s.charAt(pos[0]))) {
            pos[0]++;
        }
    }

    private static Object value(String s, int[] pos) {
        skip(s, pos);
        char c = s.charAt(pos[0]);
        if (c == '{') {
            Map<String, Object> map = new LinkedHashMap<>();
            pos[0]++;
            skip(s, pos);
            if (s.charAt(pos[0]) == '}') {
                pos[0]++;
                return map;
            }
            while (true) {
                skip(s, pos);
                String key = string(s, pos);
                skip(s, pos);
                pos[0]++; // ':'
                map.put(key, value(s, pos));
                skip(s, pos);
                if (s.charAt(pos[0]++) == '}') {
                    return map;
                }
            }
        }
        if (c == '[') {
            List<Object> list = new ArrayList<>();
            pos[0]++;
            skip(s, pos);
            if (s.charAt(pos[0]) == ']') {
                pos[0]++;
                return list;
            }
            while (true) {
                list.add(value(s, pos));
                skip(s, pos);
                if (s.charAt(pos[0]++) == ']') {
                    return list;
                }
            }
        }
        if (c == '"') {
            return string(s, pos);
        }
        if (s.startsWith("true", pos[0])) {
            pos[0] += 4;
            return Boolean.TRUE;
        }
        if (s.startsWith("false", pos[0])) {
            pos[0] += 5;
            return Boolean.FALSE;
        }
        if (s.startsWith("null", pos[0])) {
            pos[0] += 4;
            return null;
        }
        int start = pos[0];
        while (pos[0] < s.length() && "+-0123456789.eE".indexOf(s.charAt(pos[0])) >= 0) {
            pos[0]++;
        }
        String number = s.substring(start, pos[0]);
        if (number.contains(".") || number.contains("e") || number.contains("E")) {
            return Double.parseDouble(number);
        }
        BigInteger big = new BigInteger(number);
        return big.bitLength() < 64 ? (Object) big.longValue() : big;
    }

    private static String string(String s, int[] pos) {
        StringBuilder out = new StringBuilder();
        pos[0]++; // opening quote
        while (true) {
            char c = s.charAt(pos[0]++);
            if (c == '"') {
                return out.toString();
            }
            if (c != '\\') {
                out.append(c);
                continue;
            }
            char e = s.charAt(pos[0]++);
            switch (e) {
                case 'n': out.append('\n'); break;
                case 't': out.append('\t'); break;
                case 'r': out.append('\r'); break;
                case 'b': out.append('\b'); break;
                case 'f': out.append('\f'); break;
                case 'u':
                    out.append((char) Integer.parseInt(s.substring(pos[0], pos[0] + 4), 16));
                    pos[0] += 4;
                    break;
                default: out.append(e);
            }
        }
    }

    // ---- write ----

    /** JSON text of a Java value; floats JSON cannot carry become {"$num": ...}. */
    public static String write(Object v) {
        StringBuilder out = new StringBuilder();
        write(out, v);
        return out.toString();
    }

    private static void write(StringBuilder out, Object v) {
        if (v == null) {
            out.append("null");
        } else if (v instanceof String || v instanceof Character) {
            quote(out, v.toString());
        } else if (v instanceof Double || v instanceof Float) {
            double d = ((Number) v).doubleValue();
            if (Double.isNaN(d)) {
                out.append("{\"$num\":\"NaN\"}");
            } else if (Double.isInfinite(d)) {
                out.append(d > 0 ? "{\"$num\":\"Infinity\"}" : "{\"$num\":\"-Infinity\"}");
            } else if (d == 0 && 1 / d < 0) {
                out.append("{\"$num\":\"-0\"}");
            } else if (d == Math.rint(d) && Math.abs(d) < 1e16) {
                out.append(Long.toString((long) d)).append(".0");
            } else {
                out.append(Double.toString(d).replace("E", "e"));
            }
        } else if (v instanceof Number || v instanceof Boolean) {
            out.append(v.toString());
        } else if (v instanceof Optional) {
            write(out, ((Optional<?>) v).orElse(null));
        } else if (v instanceof Map) {
            out.append('{');
            boolean first = true;
            for (Map.Entry<?, ?> e : ((Map<?, ?>) v).entrySet()) {
                if (!first) {
                    out.append(',');
                }
                first = false;
                quote(out, String.valueOf(e.getKey()));
                out.append(':');
                write(out, e.getValue());
            }
            out.append('}');
        } else if (v instanceof Collection) {
            out.append('[');
            boolean first = true;
            for (Object x : (Collection<?>) v) {
                if (!first) {
                    out.append(',');
                }
                first = false;
                write(out, x);
            }
            out.append(']');
        } else if (v.getClass().isArray()) {
            List<Object> items = new ArrayList<>();
            for (int i = 0; i < Array.getLength(v); i++) {
                items.add(Array.get(v, i));
            }
            write(out, items);
        } else {
            out.append("{\"$object\":");
            quote(out, v.getClass().getName());
            out.append('}');
        }
    }

    private static void quote(StringBuilder out, String s) {
        out.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': out.append("\\\""); break;
                case '\\': out.append("\\\\"); break;
                case '\n': out.append("\\n"); break;
                case '\t': out.append("\\t"); break;
                case '\r': out.append("\\r"); break;
                default:
                    if (Character.isHighSurrogate(c) && i + 1 < s.length()
                            && Character.isLowSurrogate(s.charAt(i + 1))) {
                        // A whole pair goes as the character: EmberJson joins an escaped pair
                        // wrongly on planes 2, 4, ... 16.
                        out.append(c).append(s.charAt(++i));
                    } else if (c < 0x20 || Character.isSurrogate(c)) {
                        // Escaped lone halves stay intact through any UTF-8 layer.
                        out.append(String.format("\\u%04x", (int) c));
                    } else {
                        out.append(c);
                    }
            }
        }
        out.append('"');
    }

    // ---- convert ----

    private static double number(Object v) {
        if (v instanceof Number) {
            return ((Number) v).doubleValue();
        }
        if (v instanceof Map && ((Map<?, ?>) v).containsKey("$num")) {
            switch (String.valueOf(((Map<?, ?>) v).get("$num"))) {
                case "NaN": return Double.NaN;
                case "Infinity": return Double.POSITIVE_INFINITY;
                case "-Infinity": return Double.NEGATIVE_INFINITY;
                case "-0": return -0.0;
                default: break;
            }
        }
        throw new Mismatch("not a number: " + v);
    }

    private static long integer(Object v, long min, long max) {
        if (v instanceof Long || v instanceof Integer) {
            long n = ((Number) v).longValue();
            if (n >= min && n <= max) {
                return n;
            }
        }
        throw new Mismatch("not an integer in range: " + v);
    }

    /** Converts a parsed JSON value to {@code type}. */
    public static Object convert(Object v, Type type) {
        if (type instanceof ParameterizedType) {
            ParameterizedType p = (ParameterizedType) type;
            Class<?> raw = (Class<?>) p.getRawType();
            Type[] args = p.getActualTypeArguments();
            if (Optional.class.equals(raw)) {
                return v == null ? Optional.empty() : Optional.of(convert(v, args[0]));
            }
            if (v == null) {
                return null;
            }
            if (Map.class.isAssignableFrom(raw)) {
                if (!(v instanceof Map)) {
                    throw new Mismatch("not an object");
                }
                Map<String, Object> out = new LinkedHashMap<>();
                for (Map.Entry<?, ?> e : ((Map<?, ?>) v).entrySet()) {
                    out.put((String) e.getKey(), convert(e.getValue(), args[1]));
                }
                return out;
            }
            if (Iterable.class.isAssignableFrom(raw)) {
                if (!(v instanceof List)) {
                    throw new Mismatch("not an array");
                }
                List<Object> out = new ArrayList<>();
                for (Object x : (List<?>) v) {
                    out.add(convert(x, args[0]));
                }
                return out;
            }
            throw new Mismatch("unsupported type " + type);
        }
        if (type instanceof GenericArrayType) {
            return array(v, ((GenericArrayType) type).getGenericComponentType());
        }
        Class<?> c = (Class<?>) type;
        if (c.isArray()) {
            return array(v, c.getComponentType());
        }
        if (v == null) {
            if (c.isPrimitive()) {
                throw new Mismatch("null for " + c);
            }
            return null;
        }
        if (c == String.class || c == CharSequence.class) {
            if (!(v instanceof String)) {
                throw new Mismatch("not a string");
            }
            return v;
        }
        if (c == int.class || c == Integer.class) {
            return (int) integer(v, Integer.MIN_VALUE, Integer.MAX_VALUE);
        }
        if (c == long.class || c == Long.class) {
            return integer(v, Long.MIN_VALUE, Long.MAX_VALUE);
        }
        if (c == short.class || c == Short.class) {
            return (short) integer(v, Short.MIN_VALUE, Short.MAX_VALUE);
        }
        if (c == byte.class || c == Byte.class) {
            return (byte) integer(v, Byte.MIN_VALUE, Byte.MAX_VALUE);
        }
        if (c == double.class || c == Double.class) {
            return number(v);
        }
        if (c == float.class || c == Float.class) {
            return (float) number(v);
        }
        if (c == boolean.class || c == Boolean.class) {
            if (!(v instanceof Boolean)) {
                throw new Mismatch("not a boolean");
            }
            return v;
        }
        if (c == Object.class) {
            return v;
        }
        throw new Mismatch("unsupported type " + c);
    }

    private static Object array(Object v, Type component) {
        if (!(v instanceof List)) {
            throw new Mismatch("not an array");
        }
        List<?> list = (List<?>) v;
        Class<?> raw = component instanceof Class ? (Class<?>) component : (Class<?>) ((ParameterizedType) component).getRawType();
        Object out = Array.newInstance(raw, list.size());
        for (int i = 0; i < list.size(); i++) {
            Array.set(out, i, convert(list.get(i), component));
        }
        return out;
    }
}

files.json.mojo:
# JSON for Mojo units, generated by mojo-anything: EmberJson
# (https://github.com/bgreni/EmberJson, Apache-2.0, tag 0.5.0) plus the value markers of
# mojo-anything's codecs.
#
# - Non-finite floats and -0.0 cross as `{"$num": "NaN" | "Infinity" | "-Infinity" | "-0"}`:
#   build floats with `json_float`, read them with `as_float`. `write_json` turns any other
#   non-finite float into its marker too (EmberJson alone would write NaN as `null`).
# - Integers stay exact up to the 64-bit limits (`Int64` and `UInt64`). Beyond them a token is
#   read as a float, or refused with `refuse_big_ints=True` (Ruby's bignums); EmberJson refuses
#   a lone surrogate (`"\ud800"`). Nothing is changed silently.
# - Object keys keep their order. Nesting is limited to EmberJson's 1024 levels.

from emberjson import Array, Object, Value, from_json, to_json
from std.memory import bitcast
from std.utils.numerics import inf, isinf, isnan, nan

comptime JsonValue = Value
"""The JSON value a port takes and returns."""

comptime _U64_MAX = "18446744073709551615"
comptime _I64_MIN_ABS = "9223372036854775808"


def _beyond(digits: String, limit: String) -> Bool:
    """Whether the decimal `digits` (no sign, no leading zeros) exceed `limit`."""
    var d = len(digits.as_bytes())
    var l = len(limit.as_bytes())
    if d != l:
        return d > l
    return digits > limit


def _refuse_big_ints(text: String) raises:
    """Raises for an integer token beyond the 64-bit limits, which EmberJson reads as a float."""
    var b = text.as_bytes()
    var i = 0
    var n = len(b)
    while i < n:
        var c = b[i]
        if c == 34:
            i += 1
            while i < n and b[i] != 34:
                i += 2 if b[i] == 92 else 1
            i += 1
            continue
        if c == 45 or (c >= 48 and c <= 57):
            var start = i
            var negative = c == 45
            if negative:
                i += 1
            var digits_start = i
            while i < n and b[i] >= 48 and b[i] <= 57:
                i += 1
            var integer = not (i < n and (b[i] == 46 or b[i] == 101 or b[i] == 69))
            if integer and i > digits_start:
                var digits = String(text[byte = digits_start:i])
                var limit = _I64_MIN_ABS if negative else _U64_MAX
                if _beyond(digits, limit):
                    raise Error(
                        "json: the integer "
                        + String(text[byte = start:i])
                        + " at byte "
                        + String(start)
                        + " is beyond 64 bits, which mojo-anything's JSON does not carry yet"
                    )
            while i < n and b[i] != 44 and b[i] != 93 and b[i] != 125 and b[i] > 32:
                i += 1
            continue
        i += 1


def parse_json(text: String, refuse_big_ints: Bool = False) raises -> Value:
    """Reads one JSON value. Raises for malformed JSON, a lone surrogate or nesting deeper than
    1024 levels.

    An integer token beyond the 64-bit limits reads as the nearest float: V8 and Go write large
    floats that way (`123456789012345680000`). Ruby writes its floats with a `.` or an exponent,
    so such a token from Ruby is a bignum, which this JSON cannot carry: its dispatcher passes
    `refuse_big_ints=True` to raise instead of changing the value."""
    if refuse_big_ints:
        _refuse_big_ints(text)
    return from_json[Value](text)


def json_float(x: Float64) -> Value:
    """`x` as a JSON value: a `$num` marker for NaN, the infinities and -0.0."""
    var marker: String
    if isnan(x):
        marker = "NaN"
    elif isinf(x):
        marker = "Infinity" if x > 0 else "-Infinity"
    elif x == 0.0 and (bitcast[DType.uint64](x) >> 63) == 1:
        marker = "-0"
    else:
        return Value(x)
    var o = Object()
    o["$num"] = Value(marker)
    return Value(o^)


def as_float(v: Value) raises -> Float64:
    """The number `v` holds, reading `$num` markers and integers."""
    if v.is_float():
        return v.float()
    if v.is_int():
        return v.int().cast[DType.float64]()
    if v.is_uint():
        return v.uint().cast[DType.float64]()
    if v.is_object() and len(v.object()) == 1 and "$num" in v.object():
        ref m = v.object()["$num"]
        if m.is_string():
            var s = m.string()
            if s == "NaN":
                return nan[DType.float64]()
            if s == "Infinity":
                return inf[DType.float64]()
            if s == "-Infinity":
                return -inf[DType.float64]()
            if s == "-0":
                return -0.0
    raise Error("json: expected a number, got " + to_json(v))


def _kind(v: Value) -> String:
    if v.is_null():
        return "null"
    if v.is_bool():
        return "a bool"
    if v.is_int() or v.is_uint() or v.is_float():
        return "a number"
    if v.is_string():
        return "a string"
    if v.is_array():
        return "an array"
    return "an object"


def json_int(v: Value, lo: Int64, hi: Int64) raises -> Int64:
    """The integer `v` holds, raising unless it lies in `lo`..`hi`."""
    var x: Int64
    if v.is_int():
        x = v.int()
    elif v.is_uint() and v.uint() <= UInt64(Int64.MAX):
        x = Int64(v.uint())
    elif v.is_uint():
        raise Error("the integer " + String(v.uint()) + " is out of range")
    else:
        raise Error("expected an integer, got " + _kind(v))
    if x < lo or x > hi:
        raise Error("the integer " + String(x) + " is out of range")
    return x


def json_uint(v: Value, hi: UInt64) raises -> UInt64:
    """The unsigned integer `v` holds, raising unless it lies in 0..`hi`."""
    var x: UInt64
    if v.is_uint():
        x = v.uint()
    elif v.is_int() and v.int() >= 0:
        x = UInt64(v.int())
    elif v.is_int():
        raise Error("the integer " + String(v.int()) + " is out of range")
    else:
        raise Error("expected an integer, got " + _kind(v))
    if x > hi:
        raise Error("the integer " + String(x) + " is out of range")
    return x


def json_string(v: Value) raises -> String:
    """The string `v` holds."""
    if not v.is_string():
        raise Error("expected a string, got " + _kind(v))
    return v.string()


def json_bool(v: Value) raises -> Bool:
    """The bool `v` holds."""
    if not v.is_bool():
        raise Error("expected a bool, got " + _kind(v))
    return v.bool()


def json_array(v: Value) raises:
    """Raises unless `v` is an array."""
    if not v.is_array():
        raise Error("expected an array, got " + _kind(v))


def _marked(v: Value) -> Value:
    """`v` with every non-finite or negative-zero float replaced by its marker."""
    if v.is_float():
        return json_float(v.float())
    if v.is_array():
        var out = Array()
        for item in v.array():
            out.append(_marked(item))
        return Value(out^)
    if v.is_object():
        var out = Object()
        for kv in v.object().items():
            out[kv.key] = _marked(kv.value)
        return Value(out^)
    return v.copy()


def write_json(v: Value) raises -> String:
    """`v` as compact JSON, with `$num` markers for non-finite floats and -0.0."""
    return to_json(_marked(v))

