#include "checksum.h"

static const uint32_t MOD_ADLER = 65521;

uint32_t adler32(const char *data) {
    uint32_t a = 1, b = 0;
    if (!data) return 0;
    for (const unsigned char *p = (const unsigned char *)data; *p; p++) {
        a = (a + *p) % MOD_ADLER;
