        for (size_t i = 0; i < body_len; i++) body[i] = (char)toupper((unsigned char)body[i]);
        respond(fd, 200, TEXT, body, body_len);
    } else if (!strcmp(method, "GET") && !strncmp(target, "/div/", 5)) {
        char *a = target + 5;
        char *slash = strchr(a, '/');
        if (!slash || strchr(slash + 1, '/')) {
            text(fd, 404, "not found\n");
            return;
