    var cps = List[Int]()
    cps.append(cp)
    return _encode(cps)


def _cased(cp: Int) -> Bool:
    var s = _one(cp)
    return s.lower() != s or s.upper() != s


def _case_ignorable(cp: Int) -> Bool:
    return (
        (cp >= 0x300 and cp <= 0x36F)
        or cp == 0x27
        or cp == 0xAD
        or cp == 0xB7
