    for j in range(len(keys)):
        o[keys[j]] = JsonValue(Int64(counts[j]))
    return JsonValue(o^)


# Port of `gcd`.
def gcd(a: Int64, b: Int64) raises -> Int64:
    var x = _abs(a)
    var y = _abs(b)
