            raise Error(bad)
        i += 1
        if i == last:
            raise Error(bad)
    var multmin: Int64 = -922337203685477580
    var result: Int64 = 0
    while i < last:
        var d = _digit(cps[i])
        if d < 0 or result < multmin:
            raise Error(bad)
        result *= 10
        if result < limit + Int64(d):
            raise Error(bad)
        result -= Int64(d)
        i += 1
    return result if negative else -result

