    return a + b


@export
def probe_len(s: Optional[Pointer[Int8, ImmutAnyOrigin]]) abi("C") -> UInt:
    if not s:
        return UInt.MAX
    var p = s.value()
    var n = 0
    while p[unsafe_offset=n] != 0:
        n += 1
    return UInt(n)


@export
def probe_fill(buf: Pointer[UInt8, MutAnyOrigin], n: UInt) abi("C"):
    for i in range(Int(n)):
        buf[unsafe_offset=i] = UInt8(i)


