    return Pair(p.a * 2, p.b * 2)


@export
def probe_end(
    s: Pointer[Int8, ImmutAnyOrigin],
    end: Pointer[Pointer[Int8, ImmutAnyOrigin], MutAnyOrigin],
) abi("C"):
    end[] = s.unsafe_offset(2)

