        free(buf);
        printf("copied %zu bytes\n", len);
    } else if (!strcmp(cmd, "now")) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("now: %lld%09ld\n", (long long)ts.tv_sec, ts.tv_nsec);
    } else {
        return usage();
    }
